"""Original obesity chapter: postoperative safety and metabolic phenotypes."""
from create_obesity import rows,q,OB,PH,SU
from qbank_authoring import ref,finalize
NU=ref('BOMSS: Biochemical Monitoring and Micronutrient Replacement, 2020','https://pmc.ncbi.nlm.nih.gov/articles/PMC7583474/')
MA=ref('EASL/EASD/EASO: MASLD Guideline, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11299976/')
WE=ref('FDA: Wegovy Label Including MASH Indication, 2025','https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/215256s023lbl.pdf')
OA=ref('FDA: Tirzepatide Approval for Obstructive Sleep Apnea','https://www.fda.gov/news-events/press-announcements/fda-approves-first-medication-obstructive-sleep-apnea')
LD=ref('Multi-Society Guideline: Lipodystrophy Syndromes','https://pmc.ncbi.nlm.nih.gov/articles/PMC5155679/')
q('A patient is well one year after gastric bypass and asks to stop all supplementation and blood tests. What is the best advice?', 'Continue lifelong nutritional surveillance and procedure-appropriate supplements',[
 ('Normal weight proves all micronutrient stores are adequate','Body weight does not establish nutritional sufficiency.'),('Only the first postoperative month requires monitoring','Deficiencies can emerge years later.'),('All procedures have identical deficiency risks','Anatomy and intake change the risk pattern.')],
 'The operation changes nutrient handling beyond the weight-loss phase', '**Iron, B12, folate, vitamin D and other deficits can develop.**',['The procedure determines additional monitoring needs.','Adherence and symptoms should be reviewed alongside blood tests.'], '**Use a clear shared-care follow-up plan.**',['Pregnancy, vomiting or rapid additional loss increases concern.','Do not assume a standard multivitamin alone covers every patient.'],[['Duration','Lifelong follow-up'],['Risk','Procedure and intake dependent'],['Plan','Supplements plus biochemical surveillance']],[NU],'clinical_scenario')
q('Repeated vomiting after bariatric surgery is followed by gait ataxia and confusion. What should be done immediately?', 'Treat suspected thiamine deficiency promptly with an appropriate parenteral regimen while evaluating the vomiting',[
 ('Wait for the thiamine level before treatment','Delay can cause irreversible neurological harm.'),('Give only folate and defer neurological assessment','The syndrome raises concern for Wernicke encephalopathy.'),('Assume vomiting is always a normal expected effect','A stricture or other treatable complication may be present.')],
 'Thiamine stores can be depleted rapidly with poor intake', '**BOMSS advises immediate treatment when deficiency is suspected.**',['The full classic triad is often absent.','Magnesium and other deficits can coexist.'], '**Treat the cause and support nutrition.**',['Give thiamine before or alongside carbohydrate when feasible, without delaying lifesaving glucose for hypoglycemia.','Do not rely on a normal-looking weight or supplement prescription.'],[['Risk','Vomiting and poor intake'],['Concern','Wernicke encephalopathy'],['Action','Immediate thiamine and cause evaluation']],[NU],'clinical_scenario')
q('Edema and low albumin develop after a malabsorptive bariatric procedure. What is the appropriate assessment?', 'Evaluate protein intake and absorption while excluding liver, kidney and other causes of hypoalbuminemia',[
 ('The edema proves simple excess calorie intake','Protein malnutrition can occur despite the original obesity history.'),('All low albumin after surgery is a harmless assay change','It can signal important nutritional or systemic disease.'),('Treat only with a diuretic without evaluating intake','This misses the potential underlying deficit.')],
 'Weight reduction can coexist with serious malnutrition', '**Low intake, intolerance, strictures and malabsorption can reduce protein availability.**',['Other organ causes still require assessment.','Loss of lean tissue can worsen function.'], '**Use urgent bariatric and dietetic review when severe.**',['Correct deficits and the anatomical or behavioral cause.','Monitor refeeding risk in a severely depleted patient.'],[['Finding','Edema/hypoalbuminemia'],['Possible mechanism','Protein deficiency'],['Work-up','Nutrition plus systemic causes']],[NU],'clinical_scenario')
q('Soon after a carbohydrate-rich meal, a gastric-bypass patient develops palpitations, flushing, cramping and diarrhea without documented hypoglycemia. Which mechanism is likely?', 'Early dumping from rapid nutrient delivery and fluid/hormonal responses',[
 ('Every postmeal symptom proves late hyperinsulinemic hypoglycemia','Early dumping and confirmed post-bariatric hypoglycemia are distinct.'),('A fasting insulinoma is established','The immediate meal timing and GI symptoms suggest another mechanism.'),('An OGTT is required in every case to provoke symptoms','Provocation can be misleading and is not routinely required.')],
 'Timing helps separate postoperative syndromes', '**Early dumping occurs relatively soon after eating and can include vasomotor and gastrointestinal symptoms.**',['Later confirmed hypoglycemia usually occurs hours after meals.','Other postoperative causes need assessment when the presentation is atypical.'], '**Begin with targeted dietetic strategies.**',['Meal size, composition and fluid timing can help.','Document glucose during suspected lows rather than assuming all symptoms are hypoglycemic.'],[['Early phase','Rapid transit/fluid and hormonal effects'],['Later low glucose','Different hypoglycemic mechanism'],['Assessment','Timing and objective findings']],[NU,SU],'clinical_scenario')
q('What is central to the MASLD classification in an adult with hepatic steatosis?', 'At least one cardiometabolic risk factor with assessment of alcohol exposure and alternative causes',[
 ('Every fatty liver is automatically the same metabolic category','Alcohol and other etiologies affect classification.'),('A normal BMI excludes MASLD','Metabolic dysfunction can occur at lower BMI.'),('An elevated ALT is required in every case','Steatosis and fibrosis can exist with normal enzymes.')],
 'The nomenclature incorporates metabolic context', '**MASLD spans steatosis, inflammatory MASH and varying fibrosis stages.**',['Diabetes, adiposity and other metabolic features influence risk.','Alcohol exposure must be quantified rather than guessed.'], '**Assess fibrosis and cardiovascular risk.**',['The category alone does not stage liver injury.','Evaluate other causes when clinical features suggest them.'],[['Steatosis','Required liver-fat context'],['Metabolic risk','At least one feature'],['Next question','Fibrosis and competing etiologies']],[MA])
q('A patient with type 2 diabetes and steatotic liver has normal ALT. What is the correct fibrosis-assessment principle?', 'Normal aminotransferases do not exclude advanced fibrosis',[
 ('Normal ALT guarantees absence of clinically important liver disease','Enzymes can be normal despite fibrosis.'),('Only liver fat quantity determines prognosis','Fibrosis stage is a major liver-outcome determinant.'),('A1C alone directly measures fibrosis','It is not a fibrosis test.')],
 'Enzyme activity and accumulated scar are different dimensions', '**High-risk metabolic patients need appropriate noninvasive fibrosis assessment.**',['FIB-4 is a common first step.','Elastography or other validated tests refine intermediate or high risk.'], '**Use a multistep pathway.**',['Avoid reassurance based on one normal enzyme.','Interpret scores cautiously in acute illness and age extremes.'],[['ALT','May be normal'],['Fibrosis','Still possible'],['Assessment','Stepwise noninvasive testing']],[MA],'clinical_scenario')
q('A 55-year-old with MASLD has FIB-4 1.9. Which next assessment is appropriate?', 'A second-line fibrosis test such as transient elastography according to the local pathway',[
 ('The result definitively proves cirrhosis','An intermediate score is not a histological diagnosis.'),('Ignore because ALT is only mildly raised','Fibrosis evaluation is not determined by ALT alone.'),('Immediate liver transplantation assessment in every case','This is disproportionate without evidence of advanced failure.')],
 'A first-line score sorts risk rather than confirming all stages', '**EASL uses a common threshold above 1.3 for additional assessment in this age group.**',['For adults above 65, a higher 2.0 threshold is used in the pathway.','FIB-4 performs less well in some young adults and during acute illness.'], '**Use the next test to refine referral and follow-up.**',['Do not stack unvalidated thresholds from different pathways.','Treat metabolic risk regardless of the fibrosis result.'],[['Age 55/FIB-4 1.9','Intermediate-risk context'],['Next test','Elastography or equivalent'],['Purpose','Refine fibrosis risk']],[MA],'clinical_scenario')
q('Which weight-loss relationship is supported by EASL 2024 guidance for MASLD with overweight?', 'About 5% can reduce liver fat, 7–10% can improve inflammation and at least 10% is associated with fibrosis improvement',[
 ('Any 1% loss guarantees complete fibrosis reversal','Benefits are not guaranteed at that small change.'),('Only weight loss above 40% can affect liver fat','Meaningful hepatic effects occur with more modest sustained loss.'),('Improved ALT always proves all scar has disappeared','Enzyme change is not proof of fibrosis resolution.')],
 'Different liver outcomes require different degrees of sustained change', '**The stated targets describe expected associations, not promises for an individual.**',['Nutrition, physical activity and metabolic treatment are complementary.','Cardiovascular health remains a major priority.'], '**Choose a sustainable strategy.**',['Use medication or metabolic surgery when appropriately indicated.','Assess lean mass and nutrition during substantial loss.'],[['At least 5%','Less steatosis'],['7–10%','Inflammatory improvement'],['At least 10%','Fibrosis improvement more likely']],[MA])
q('Which liver indication was added to the U.S. Wegovy injection label in 2025?', 'Noncirrhotic MASH with moderate-to-advanced fibrosis consistent with F2–F3 in adults',[
 ('Every form of decompensated cirrhosis regardless of cause','That is not the specified indication.'),('All asymptomatic steatosis without fibrosis evaluation','The label defines a particular MASH/fibrosis population.'),('A permanent cure for every liver disease','The treatment has a defined indication and continuing outcome requirements.')],
 'A newer indication changes an older “no approved GLP-1 MASH therapy” statement', '**The U.S. approval was accelerated on improvement in MASH and fibrosis.**',['It is used with reduced-calorie nutrition and increased activity.','The indication does not automatically apply in every country.'], '**Confirm the patient matches the disease and fibrosis criteria.**',['Review the current label, contraindications and follow-up.','Do not generalize from this approval to decompensated cirrhosis.'],[['Population','Adult noncirrhotic MASH'],['Fibrosis','F2–F3 context'],['Regulatory basis','Accelerated U.S. approval']],[WE])
q('Which statement about tirzepatide and obstructive sleep apnea is correct?', 'It has a U.S. indication for moderate-to-severe OSA in adults with obesity alongside nutrition and activity measures',[
 ('It automatically makes positive-airway-pressure assessment unnecessary in every patient','Sleep therapy and reassessment remain individualized.'),('It is approved for every central apnea syndrome','The indication is obstructive sleep apnea in the specified population.'),('It is only a sedative that improves sleep by respiratory suppression','It is a metabolic therapy with weight-related effects.')],
 'Treating obesity can improve an important respiratory consequence', '**The FDA approval followed trials showing reduced apnea burden.**',['The person’s ongoing PAP needs require sleep-medicine assessment.','Weight and symptom response vary.'], '**Do not withdraw effective respiratory treatment without reassessment.**',['Coordinate adverse-effect and metabolic monitoring.','Use the applicable local authorization.'],[['Indication','Moderate-to-severe OSA with obesity'],['Approach','Adjunct nutrition and activity'],['Sleep treatment','Reassess rather than stop automatically']],[OA])
q('Marked insulin resistance, severe hypertriglyceridemia and fatty liver occur in a lean-looking person with generalized loss of subcutaneous fat. Which diagnosis is suggestive?', 'Generalized lipodystrophy',[
 ('Low body fat guarantees high insulin sensitivity','Failure of safe fat storage can cause severe metabolic disease.'),('Ordinary starvation is proven without considering phenotype','The severe metabolic pattern and fat distribution suggest a storage disorder.'),('Every lean person with diabetes has GCK-MODY','This is a distinct phenotype.')],
 'Adipose tissue is a metabolic organ, not only an energy burden', '**Lack of functional fat storage promotes ectopic lipid and insulin resistance.**',['Leptin deficiency can contribute in generalized disease.','Congenital and acquired forms exist.'], '**Assess distribution, family history and associated disease.**',['Treat diabetes, triglycerides and liver risk aggressively but safely.','Seek a specialist diagnosis rather than inferring health from BMI.'],[['Fat storage','Deficient'],['Metabolic effect','Ectopic lipid/insulin resistance'],['Phenotype','Loss of subcutaneous fat']],[LD],'clinical_scenario')
q('Which patient group can benefit from metreleptin as a targeted metabolic treatment where approved?', 'Patients with generalized lipodystrophy and leptin-deficient metabolic complications',[
 ('All people with common obesity regardless of leptin physiology','It is not a universal routine obesity drug.'),('Every patient with isolated high LDL','That is not the targeted replacement indication.'),('Only people with hyperthyroidism','The treatment addresses a different pathway.')],
 'Hormone replacement is phenotype specific', '**Metreleptin can improve diabetes, triglycerides and other complications in selected lipodystrophy.**',['Availability and partial-lipodystrophy indications vary by region.','Serious safety warnings and immune effects require specialist oversight.'], '**Combine with nutrition and complication management.**',['Do not extrapolate a rare-disease replacement strategy to ordinary obesity.','Monitor metabolic response and the product-specific risks.'],[['Target group','Generalized lipodystrophy'],['Mechanism','Leptin replacement'],['Setting','Specialist monitored care']],[LD])

if __name__=='__main__':finalize('Endocrine',8,'Obesity and Metabolic Disease','endo-obesity-metabolic',rows,24)
